do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-012","project":"qvplwejffhjvxaypmjut","actions":[{"ref":"y0","relation":"works","key":{"id":334},"before":{"id":334,"title":"Candide","cover_id":null,"subjects":null,"subtitle":null,"author_id":209,"work_type":null,"created_at":"2026-09-02T08:30:57.857895+00:00","source_type":"open_library","open_library_id":"OL100672W","first_publish_year":1746,"native_identity_key":null},"after":{"id":334,"title":"Candide","cover_id":null,"subjects":null,"subtitle":null,"author_id":209,"work_type":null,"created_at":"2026-09-02T08:30:57.857895+00:00","source_type":"open_library","open_library_id":"OL100672W","first_publish_year":1759,"native_identity_key":null}},{"ref":"e0","relation":"editions","key":{"open_library_edition_id":"OL24328781M"},"before":null,"after":{"work_id":334,"title":"Candide, of Het optimisme","language":"dut","open_library_edition_id":"OL24328781M","isbn_13":"9789029554343","isbn_10":null,"publisher":"De Arbeiderpers"}},{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":334,"language":"nl"},"before":null,"after":{"work_id":334,"language":"nl","bound_author_id":209,"text":"Candide groeit op met de overtuiging dat alles uiteindelijk zo goed mogelijk geregeld is. Wanneer zijn liefde voor de dochter van een baron wordt ontdekt, moet hij de beschermde omgeving verlaten. Tijdens reizen door verschillende werelddelen krijgt hij vervolgens met geweld, rampen en willekeur te maken. Zijn ervaringen botsen steeds opnieuw met de geruststellende lessen van zijn leermeester Pangloss. Voltaire gebruikt die tegenstelling om vastgeroeste zekerheden en het gemak van theoretisch optimisme te bevragen.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://candide.bnf.fr/reperes","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p03620532X"],"reference":"work:334","checked_at":"2026-11-02T