data.bibliotheken.nl/id/nbt/p041486617","http://data.bibliotheken.nl/id/nbt/p411877461","http://data.bibliotheken.nl/id/nbt/p371669065"],"reference":"work:1193","checked_at":"2026-11-02T19:50:00.000Z","note":"Couperus ElineVere: same novel, distinct1888serial/1889book dates retained without new year correction. Hardback is an explicit print synonym. First book edition1889, preceding newspaper serial1888 and later third printing1892 explicitly distinguished. Correct current1892to first book1889. Exact new Veen print is not guessed to be the legacy ISBN-less edition.","supplemental":null},{"type":"original_substantive_source_review","review":"content-review-020.json","sources":["https://www.dbnl.org/tekst/anbe001lexi01_01/lvlw00134.php?q=gemoderniseerd","https://www.dbnl.org/titels/titel.php?id=coup002elin01","https://www.dbnl.org/tekst/coup002elin01_01/colofon.php","https://www.bibliotheek.nl/catalogus/titel.436207516.html/eline-vere/","https://openlibrary.org/works/OL1456910W","https://data.bibliotheken.nl/id/nbt/p041486617","https://data.bibliotheken.nl/id/nbt/p411877461","https://data.bibliotheken.nl/id/nbt/p371669065"]},{"type":"cover_front_review","cover_id":6759584,"sha256":"8a3aa08fb4d75f4d69a3ca1af57ca83db0d5dfce09f092ca8a96e32e5e3f919a","reference":"cover-semantic-review-010.json","limitation":"Actually read cover-large/sheet-001.jpg. Louis Couperus; Eline Vere; Veen uitgevers. Front identity and source-edition attachment are corroboration, not proof of a visible barcode, printing year, language or complete contents. Bibliographic checks remain separate."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T19:50:00.000Z","review_batch":"nl-scale-20261102-012"}},{"ref":"m5","relation":"catalog_edition_metadata","key":{"edition_id":"@e5"},"before":null,"after":{"edition_id":"@e5","work_id":1193,"bound_author_id":700,"bound_title":"Eline Vere","bound_language":"dut","bound_isbn13":"9789020425895","format":"hard